<template>
  <div class="tictactoe-game">
    <h1>井字棋对战</h1>

    <div v-if="hasError" class="error-message">
      <p>⚠️ {{ errorMessage }}</p>
      <button class="close-btn" @click="clearError">关闭</button>
    </div>

    <div class="game-info">
      <div class="game-info-header">
        <div class="player-info">
          <div class="player x">
            <span class="mark x">X</span>
            <span>X方：{{ internalGameData.xPlayer?.name || "X方" }}</span>
            <span
v-if="internalGameData.ranks && internalGameData.ranks[0] !== undefined" 
                  :class="['rank', internalGameData.ranks[0] >= 0 ? 'positive' : 'negative']">
              {{ internalGameData.ranks[0] > 0 ? "+" : "" }}{{ internalGameData.ranks[0] }}
            </span>
          </div>
          <div class="player o">
            <span class="mark o">O</span>
            <span>O方：{{ internalGameData.oPlayer?.name || "O方" }}</span>
            <span
v-if="internalGameData.ranks && internalGameData.ranks[1] !== undefined" 
                  :class="['rank', internalGameData.ranks[1] >= 0 ? 'positive' : 'negative']">
              {{ internalGameData.ranks[1] > 0 ? "+" : "" }}{{ internalGameData.ranks[1] }}
            </span>
          </div>
        </div>
        <div class="game-status">
          <p v-if="internalGameData.result">结果：{{ internalGameData.result }}</p>
          <p>当前步数：{{ currentStep }} / {{ internalGameData.moves?.length || 0 }}</p>
        </div>
      </div>
      <div v-if="internalGameData.message" class="game-message">
        <p class="message-content">{{ internalGameData.message }}</p>
      </div>
    </div>

    <div class="board-container">
      <canvas ref="boardCanvas" :width="canvasWidth" :height="canvasHeight" class="tictactoe-board"></canvas>
    </div>

    <div class="controls">
      <button class="control-btn" @click="gotoStart"><span>⏮️</span> 开始</button>
      <button class="control-btn" @click="prevStep"><span>⏪</span> 上一步</button>
      <button class="control-btn primary" @click="togglePlay">
        <span v-if="isPlaying">⏸️</span>
        <span v-else>▶️</span>
        {{ isPlaying ? "暂停" : "播放" }}
      </button>
      <button class="control-btn" @click="nextStep"><span>⏩</span> 下一步</button>
      <button class="control-btn" @click="gotoEnd"><span>⏭️</span> 结束</button>
      <div class="speed-control">
        <label>播放速度：</label>
        <input v-model="playSpeed" type="range" min="0.5" max="3" step="0.5" class="speed-slider" />
        <span>{{ playSpeed }}x</span>
      </div>
    </div>

    <div class="move-history">
      <h3>落子记录</h3>
      <div class="moves">
        <div
v-for="(move, index) in internalGameData.moves" :key="index"
          :class="['move-item', { active: index === currentStep - 1 }]" @click="gotoStep(index + 1)">
          <span class="move-number">{{ index + 1 }}</span>
          <span class="mark" :class="move.mark">{{ move.mark.toUpperCase() }}</span>
          <span class="move-position">{{ formatPosition(move.x, move.y) }}</span>
          <span v-if="move.time" class="timestamp">{{ formatTime(move.time) }}</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, watch, onUnmounted } from "vue";
import type { GenericGameData } from "@/types/bot";
import { useBreakpoint } from "@/composables/useBreakpoint";

// 判断是否为非空对象，供类型守卫内部收窄使用
const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

function isGenericGameData(data: unknown): data is GenericGameData {
  if (!isRecord(data)) {
    return false;
  }
  return (
    typeof data.id === "string" &&
    data.id.length > 0 &&
    typeof data.gameKey === "string" &&
    typeof data.gameTitle === "string" &&
    typeof data.status === "number" &&
    typeof data.infoData === "object" &&
    data.infoData !== null &&
    typeof data.paramData === "object" &&
    data.paramData !== null &&
    Array.isArray(data.agents)
  );
}

function validateMove(move: unknown): move is { x: number; y: number; time?: number } {
  if (!isRecord(move)) {
    return false;
  }
  return (
    typeof move.x === "number" &&
    typeof move.y === "number" &&
    move.x >= 0 &&
    move.y >= 0 &&
    (move.time === undefined || typeof move.time === "number")
  );
}

function validateMoves(moves: unknown[]): boolean {
  if (!Array.isArray(moves)) {
    console.error("TicTacToe: moves 不是数组");
    return false;
  }

  for (let i = 0; i < moves.length; i++) {
    if (!validateMove(moves[i])) {
      console.error(`TicTacToe: moves[${i}] 数据无效:`, moves[i]);
      return false;
    }
  }

  return true;
}

const errorMessage = ref<string>("");
const hasError = ref(false);

function showError(message: string): void {
  errorMessage.value = message;
  hasError.value = true;
  console.error("TicTacToe Error:", message);
}

function clearError(): void {
  errorMessage.value = "";
  hasError.value = false;
}

interface Player {
  id: string;
  name: string;
  type?: string;
}

interface Move {
  x: number;
  y: number;
  mark: "x" | "o";
  time?: number;
}

interface GameData {
  id: string;
  boardSize: number;
  startTime?: number;
  endTime?: number;
  xPlayer: Player;
  oPlayer: Player;
  moves: Move[];
  result?: string;
  winner?: "x" | "o" | "draw";
  // 未连成三子时计算结果为 null，故这里允许 null
  winningLine?: { x1: number; y1: number; x2: number; y2: number }[] | null;
  ranks?: number[];
  message?: string;
}

const props = defineProps<{
  gameData: GenericGameData;
}>();

defineEmits<{
  (e: "update:gameData", value: GenericGameData): void;
}>();

const internalGameData = ref<GameData>({
  id: "demo-game-1",
  boardSize: 3,
  startTime: Date.now() - 3600000,
  xPlayer: {
    id: "player1",
    name: "X方选手",
    type: "bot",
  },
  oPlayer: {
    id: "player2",
    name: "O方选手",
    type: "bot",
  },
  moves: [],
  result: "游戏进行中",
});

const boardCanvas = ref<HTMLCanvasElement>();
const canvasWidth = ref(480);
const canvasHeight = ref(480);
const { isMobile } = useBreakpoint();
const currentStep = ref(0);
const isPlaying = ref(false);
const playSpeed = ref(1);
let animationFrameId: number | null = null;
let lastPlayTime = 0;
let lastBlinkTime = 0;
const blinkIntensity = ref(1);

const markAnimationProgress = ref(0);
const lineAnimationProgress = ref(0);
const isMarkAnimating = ref(false);
const isLineAnimating = ref(false);
let animationStartTime = 0;
const MARK_ANIMATION_DURATION = 300;
const LINE_ANIMATION_DURATION = 600;

let lastMovesHash = "";

function convertGenericToTicTacToeData(genericData: GenericGameData): GameData {
  clearError();

  if (!isGenericGameData(genericData)) {
    showError("无效的游戏数据格式");
    return internalGameData.value;
  }

  console.log("TicTacToe: 开始转换数据", genericData);

  const result: GameData = {
    id: genericData.id,
    boardSize: 3,
    startTime: Date.now(),
    xPlayer: {
      id: "x",
      name: "X方选手",
      type: "bot",
    },
    oPlayer: {
      id: "o",
      name: "O方选手",
      type: "bot",
    },
    moves: [],
    result: "游戏进行中",
  };

  if (genericData.infoData) {
    const info = genericData.infoData;
    console.log("TicTacToe: infoData =", info);
    console.log("TicTacToe: agents =", genericData.agents);

    const xInfo = info.x;
    if (isRecord(xInfo) && genericData.agents) {
      const xAgent = genericData.agents.find((agent) => agent.id === xInfo.id);
      console.log("TicTacToe: xAgent =", xAgent, "info.x =", xInfo.id);
      if (xAgent) {
        result.xPlayer = {
          id: xAgent.id.toString(),
          name: xAgent.name,
          type: "bot",
        };
      }
    }
    const oInfo = info.o;
    if (isRecord(oInfo) && genericData.agents) {
      const oAgent = genericData.agents.find((agent) => agent.id === oInfo.id);
      console.log("TicTacToe: oAgent =", oAgent, "info.o =", oInfo.id);
      if (oAgent) {
        result.oPlayer = {
          id: oAgent.id.toString(),
          name: oAgent.name,
          type: "bot",
        };
      }
    }
  }

  console.log("TicTacToe: 转换后的玩家信息", {
    xPlayer: result.xPlayer,
    oPlayer: result.oPlayer,
  });

  if (genericData.ranks) {
    result.ranks = genericData.ranks;
  }

  const paramMoves = genericData.paramData.moves;
  if (paramMoves) {
    // 非数组或校验失败都视为数据无效（validateMoves 需要 unknown[]，故先做数组收窄）
    if (!Array.isArray(paramMoves) || !validateMoves(paramMoves)) {
      showError("落子数据格式无效");
      return result;
    }

    result.moves = paramMoves.filter(validateMove).map((move, index): Move => ({
      x: move.x,
      y: move.y,
      mark: index % 2 === 0 ? "x" : "o",
      time: move.time,
    }));

    const paramMessage = genericData.paramData.message;
    if (typeof paramMessage === "string" && paramMessage) {
      result.message = paramMessage;
    }
  }

  return result;
}

function formatPosition(x: number, y: number): string {
  const columnLabel = String.fromCharCode(65 + x);
  const rowLabel = internalGameData.value.boardSize - y;
  return `${columnLabel}${rowLabel}`;
}

function formatTime(time: number): string {
  return `${time}ms`;
}

function drawBoard(): void {
  if (!boardCanvas.value) {
    console.error("boardCanvas 元素不存在");
    return;
  }

  const ctx = boardCanvas.value.getContext("2d");
  if (!ctx) {
    console.error("无法获取 2D 上下文");
    return;
  }

  const size = internalGameData.value.boardSize;
  const padding = 60;
  const cellSize = Math.min((canvasWidth.value - padding * 2) / size, (canvasHeight.value - padding * 2) / size);
  const offsetX = padding;
  const offsetY = padding;

  ctx.clearRect(0, 0, canvasWidth.value, canvasHeight.value);

  ctx.fillStyle = "#fafafa";
  ctx.fillRect(0, 0, canvasWidth.value, canvasHeight.value);

  ctx.strokeStyle = "#2c3e50";
  ctx.lineWidth = 2;
  ctx.lineCap = "round";

  for (let i = 1; i < size; i++) {
    ctx.beginPath();
    ctx.moveTo(offsetX + i * cellSize, offsetY);
    ctx.lineTo(offsetX + i * cellSize, offsetY + size * cellSize);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(offsetX, offsetY + i * cellSize);
    ctx.lineTo(offsetX + size * cellSize, offsetY + i * cellSize);
    ctx.stroke();
  }

  ctx.font = "bold 16px Arial";
  ctx.fillStyle = "#4a5568";
  ctx.textAlign = "center";
  ctx.textBaseline = "bottom";

  for (let i = 0; i < size; i++) {
    const x = offsetX + i * cellSize + cellSize / 2;
    const columnLabel = String.fromCharCode(65 + i);
    ctx.textBaseline = "bottom";
    ctx.fillText(columnLabel, x, offsetY - 10);
    ctx.textBaseline = "top";
    ctx.fillText(columnLabel, x, offsetY + size * cellSize + 10);
  }

  for (let i = 0; i < size; i++) {
    const y = offsetY + i * cellSize + cellSize / 2;
    const rowLabel = size - i;
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    ctx.fillText(rowLabel.toString(), offsetX - 10, y);
    ctx.textAlign = "left";
    ctx.fillText(rowLabel.toString(), offsetX + size * cellSize + 10, y);
  }

  drawMarks();
}

function drawMarks(): void {
  if (!boardCanvas.value) return;

  const ctx = boardCanvas.value.getContext("2d");
  if (!ctx) return;

  const size = internalGameData.value.boardSize;
  const padding = 60;
  const cellSize = Math.min((canvasWidth.value - padding * 2) / size, (canvasHeight.value - padding * 2) / size);
  const offsetX = padding;
  const offsetY = padding;

  for (let i = 0; i < currentStep.value && i < internalGameData.value.moves.length; i++) {
    const move = internalGameData.value.moves[i];
    const centerX = offsetX + move.x * cellSize + cellSize / 2;
    const centerY = offsetY + move.y * cellSize + cellSize / 2;
    const markSize = cellSize * 0.3;

    // 绘制当前步骤的高亮背景
    if (i === currentStep.value - 1) {
      const alpha = 0.3 + 0.2 * blinkIntensity.value;
      const highlightColor = move.mark === "x" ? `rgba(231, 76, 60, ${alpha})` : `rgba(52, 152, 219, ${alpha})`;

      ctx.fillStyle = highlightColor;
      ctx.fillRect(offsetX + move.x * cellSize, offsetY + move.y * cellSize, cellSize, cellSize);
    }

    let currentAlpha = 1;
    let currentScale = 1;

    if (i === currentStep.value - 1 && isMarkAnimating.value) {
      const easeOut = 1 - Math.pow(1 - markAnimationProgress.value, 3);
      currentScale = easeOut;
      currentAlpha = easeOut;
    }

    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.scale(currentScale, currentScale);
    ctx.globalAlpha = currentAlpha;

    if (move.mark === "x") {
      ctx.strokeStyle = "#e74c3c";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-markSize, -markSize);
      ctx.lineTo(markSize, markSize);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(markSize, -markSize);
      ctx.lineTo(-markSize, markSize);
      ctx.stroke();
    } else {
      ctx.strokeStyle = "#3498db";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(0, 0, markSize, 0, Math.PI * 2);
      ctx.stroke();
    }

    ctx.restore();
  }

  const { winner, winningLine } = evaluateBoard(size, internalGameData.value.moves, currentStep.value);

  if (winner && winningLine) {
    ctx.strokeStyle = "#27ae60";
    ctx.lineWidth = 5;
    ctx.lineCap = "round";

    for (const line of winningLine) {
      const startX = offsetX + line.x1 * cellSize + cellSize / 2;
      const startY = offsetY + line.y1 * cellSize + cellSize / 2;
      const endX = offsetX + line.x2 * cellSize + cellSize / 2;
      const endY = offsetY + line.y2 * cellSize + cellSize / 2;

      if (isLineAnimating.value) {
        const easeOut = 1 - Math.pow(1 - lineAnimationProgress.value, 2);

        const currentEndX = startX + (endX - startX) * easeOut;
        const currentEndY = startY + (endY - startY) * easeOut;

        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(currentEndX, currentEndY);
        ctx.stroke();

        ctx.shadowColor = "#27ae60";
        ctx.shadowBlur = 15 * easeOut;
        ctx.beginPath();
        ctx.arc(currentEndX, currentEndY, 8, 0, Math.PI * 2);
        ctx.fillStyle = "#27ae60";
        ctx.fill();
        ctx.shadowBlur = 0;
      } else {
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
      }
    }
  }
}

function gotoStep(step: number): void {
  const prevStep = currentStep.value;
  currentStep.value = Math.max(0, Math.min(step, internalGameData.value.moves.length));

  updateGameStatus();

  if (currentStep.value > prevStep && currentStep.value <= internalGameData.value.moves.length) {
    const { winner } = evaluateBoard(internalGameData.value.boardSize, internalGameData.value.moves, currentStep.value);
    if (winner && !internalGameData.value.winner) {
      startLineAnimation();
    } else {
      startMarkAnimation();
    }
  } else {
    drawBoard();
  }
}

function startMarkAnimation() {
  isMarkAnimating.value = true;
  markAnimationProgress.value = 0;
  animationStartTime = Date.now();

  function animateMark() {
    const elapsed = Date.now() - animationStartTime;
    markAnimationProgress.value = Math.min(elapsed / MARK_ANIMATION_DURATION, 1);

    drawBoard();

    if (markAnimationProgress.value < 1) {
      requestAnimationFrame(animateMark);
    } else {
      isMarkAnimating.value = false;
    }
  }

  animateMark();
}

function startLineAnimation() {
  isLineAnimating.value = true;
  lineAnimationProgress.value = 0;
  animationStartTime = Date.now();

  function animateLine() {
    const elapsed = Date.now() - animationStartTime;
    lineAnimationProgress.value = Math.min(elapsed / LINE_ANIMATION_DURATION, 1);

    drawBoard();

    if (lineAnimationProgress.value < 1) {
      requestAnimationFrame(animateLine);
    } else {
      isLineAnimating.value = false;
    }
  }

  animateLine();
}

function gotoStart(): void {
  gotoStep(0);
}

function gotoEnd(): void {
  gotoStep(internalGameData.value.moves.length);
}

function prevStep(): void {
  gotoStep(currentStep.value - 1);
}

function nextStep(): void {
  gotoStep(currentStep.value + 1);
}

function togglePlay(): void {
  isPlaying.value = !isPlaying.value;
  if (isPlaying.value) {
    lastPlayTime = Date.now();
    playAnimation();
  } else if (animationFrameId) {
    cancelAnimationFrame(animationFrameId);
    animationFrameId = null;
  }
}

function playAnimation(): void {
  if (!isPlaying.value) return;

  const now = Date.now();
  const timeDiff = now - lastPlayTime;
  const stepInterval = 1000 / playSpeed.value;

  if (timeDiff >= stepInterval && !isMarkAnimating.value && !isLineAnimating.value) {
    if (currentStep.value < internalGameData.value.moves.length) {
      nextStep();
      lastPlayTime = now;
    } else {
      isPlaying.value = false;
      return;
    }
  }

  animationFrameId = requestAnimationFrame(playAnimation);
}

function checkWinning(
  board: Map<string, "x" | "o">,
  x: number,
  y: number,
  mark: "x" | "o",
  size: number
): { x1: number; y1: number; x2: number; y2: number }[] | null {
  const directions = [
    { dx: 1, dy: 0 },
    { dx: 0, dy: 1 },
    { dx: 1, dy: 1 },
    { dx: 1, dy: -1 },
  ];

  for (const dir of directions) {
    let count = 1;
    let startX = x;
    let startY = y;
    let endX = x;
    let endY = y;

    for (let i = 1; i < 3; i++) {
      const nx = x + dir.dx * i;
      const ny = y + dir.dy * i;
      if (nx >= 0 && nx < size && ny >= 0 && ny < size && board.get(`${nx},${ny}`) === mark) {
        count++;
        endX = nx;
        endY = ny;
      } else {
        break;
      }
    }

    for (let i = 1; i < 3; i++) {
      const nx = x - dir.dx * i;
      const ny = y - dir.dy * i;
      if (nx >= 0 && nx < size && ny >= 0 && ny < size && board.get(`${nx},${ny}`) === mark) {
        count++;
        startX = nx;
        startY = ny;
      } else {
        break;
      }
    }

    if (count >= 3) {
      return [{ x1: startX, y1: startY, x2: endX, y2: endY }];
    }
  }

  return null;
}

function evaluateBoard(
  boardSize: number,
  moves: Move[],
  currentStep: number
): { winner: "x" | "o" | null; winningLine: { x1: number; y1: number; x2: number; y2: number }[] | null } {
  const board = new Map<string, "x" | "o">();

  for (let i = 0; i < currentStep && i < moves.length; i++) {
    const move = moves[i];
    board.set(`${move.x},${move.y}`, move.mark);
  }

  for (let i = 0; i < currentStep && i < moves.length; i++) {
    const move = moves[i];
    const winningLine = checkWinning(board, move.x, move.y, move.mark, boardSize);
    if (winningLine) {
      return { winner: move.mark, winningLine };
    }
  }

  if (currentStep >= boardSize * boardSize) {
    return { winner: null, winningLine: null };
  }

  return { winner: null, winningLine: null };
}

watch(currentStep, () => {
  blinkIntensity.value = 1;
  lastBlinkTime = Date.now();
});

watch(
  () => props.gameData,
  (newData) => {
    if (!newData.paramData || !newData.paramData.moves || !Array.isArray(newData.paramData.moves)) {
      return;
    }

    const currentMoves = newData.paramData.moves;
    const movesHash = JSON.stringify(currentMoves);

    if (movesHash === lastMovesHash) {
      return;
    }

    lastMovesHash = movesHash;

    console.log("TicTacToe: 收到新的gameData:", newData);
    console.log("TicTacToe: 处理paramData:", newData.paramData);
    console.log("TicTacToe: 处理moves数据:", newData.paramData.moves);

    internalGameData.value = convertGenericToTicTacToeData(newData);

    currentStep.value = internalGameData.value.moves.length;
    console.log("TicTacToe: 设置步骤为moves长度并绘制所有标记:", internalGameData.value.moves.length);
    console.log("TicTacToe: internalGameData.moves:", internalGameData.value.moves);

    updateGameStatus();
    drawBoard();
  },
  { deep: true }
);

function updateGameStatus() {
  const size = internalGameData.value.boardSize;
  const { winner, winningLine } = evaluateBoard(size, internalGameData.value.moves, currentStep.value);

  let needsUpdate = false;
  const updatedGameData = { ...internalGameData.value };

  if (winner) {
    if (updatedGameData.winner !== winner) {
      updatedGameData.winner = winner;
      updatedGameData.result = winner === "x" ? "X方胜利" : "O方胜利";
      updatedGameData.winningLine = winningLine;
      needsUpdate = true;
    }
  } else if (currentStep.value >= size * size) {
    if (updatedGameData.result !== "平局") {
      updatedGameData.result = "平局";
      updatedGameData.winner = "draw";
      needsUpdate = true;
    }
  } else {
    if (updatedGameData.result !== "游戏进行中") {
      updatedGameData.result = "游戏进行中";
      updatedGameData.winner = undefined;
      updatedGameData.winningLine = undefined;
      needsUpdate = true;
    }
  }

  if (needsUpdate) {
    internalGameData.value = updatedGameData;
  }
}

// 响应式调整画布大小
function handleResize() {
  if (!boardCanvas.value) return;

  const container = boardCanvas.value.parentElement;
  if (container) {
    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;
    const size = Math.min(containerWidth, containerHeight);

    if (canvasWidth.value !== size || canvasHeight.value !== size) {
      canvasWidth.value = size;
      canvasHeight.value = size;
      drawBoard();
    }
  }
}

// 断点切换时主动重绘棋盘
watch(isMobile, () => {
  handleResize();
  drawBoard();
});

onMounted(() => {
  lastBlinkTime = Date.now();

  updateGameStatus();

  if (props.gameData.paramData) {
    if (props.gameData.paramData.moves && Array.isArray(props.gameData.paramData.moves)) {
      internalGameData.value = convertGenericToTicTacToeData(props.gameData);

      lastMovesHash = JSON.stringify(props.gameData.paramData.moves);

      currentStep.value = internalGameData.value.moves.length;
      drawBoard();
    }
  } else {
    console.log("TicTacToe: 初始无数据，等待watch触发后绘制棋盘");
  }

  function animateBlink() {
    if (!boardCanvas.value) {
      return;
    }

    const now = Date.now();
    const timeDiff = now - lastBlinkTime;
    const blinkPeriod = 1000;

    blinkIntensity.value = 0.5 + 0.5 * Math.sin((timeDiff * Math.PI * 2) / blinkPeriod);

    if (currentStep.value >= 0 && !isPlaying.value) {
      drawBoard();
    }

    animationFrameId = requestAnimationFrame(animateBlink);
  }

  animateBlink();

  handleResize();
  window.addEventListener("resize", handleResize);

  onUnmounted(() => {
    window.removeEventListener("resize", handleResize);
    if (animationFrameId) {
      cancelAnimationFrame(animationFrameId);
      animationFrameId = null;
    }
  });
});
</script>

